<?php
declare(strict_types=1);

/** Imports metadata only. Existing WebP files are inspected, never rewritten. */
final class MediaTransfer
{
    private array $errors=[];
    private int $bytes=0;
    private const MAX_ROWS=50000;
    private const MAX_METADATA=16777216;
    private const MAX_FILE=10485760;
    public function __construct(private PDO $db,private string $directory){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function identifier(string $v):string{if(!preg_match('/^[A-Za-z0-9_][A-Za-z0-9_$-]{0,63}$/D',$v))throw new InvalidArgumentException('Tên database không hợp lệ.');return '`'.$v.'`';}
    private function error(string $scope,string $message):void{if(count($this->errors)<100)$this->errors[]=['scope'=>$scope,'message'=>$message];}
    private static function integer(mixed $v,int $max):bool{$s=(string)$v;$bound=(string)$max;return (is_int($v)||is_string($v))&&(bool)preg_match('/^[1-9][0-9]*$/D',$s)&&(strlen($s)<strlen($bound)||strlen($s)===strlen($bound)&&strcmp($s,$bound)<=0);}
    private static function text(mixed $v,int $max):bool{return is_string($v)&&mb_check_encoding($v,'UTF-8')&&mb_strlen($v,'UTF-8')<=$max;}
    private static function timestamp(mixed $v):?string{if(!is_string($v)||!preg_match('/^[1-9][0-9]{3}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]{1,6})?$/D',$v))return null;$normal=str_contains($v,'.')?str_pad($v,26,'0'):$v.'.000000';$date=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s.u',$normal,new DateTimeZone('UTC'));return $date!==false&&$date->format('Y-m-d H:i:s.u')===$normal?$normal:null;}
    private function rows(string $database,string $table,bool $lock=false):array
    {
        $buffered=$this->db->getAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY);$this->db->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,false);$statement=null;$rows=[];
        try{$statement=$this->query('SELECT * FROM '.self::identifier($database).'.'.self::identifier($table).($lock?' FOR UPDATE':''));while($row=$statement->fetch(PDO::FETCH_ASSOC)){$this->bytes+=strlen(json_encode($row,JSON_THROW_ON_ERROR));if(count($rows)>=self::MAX_ROWS||$this->bytes>self::MAX_METADATA)throw new RuntimeException('Vượt giới hạn metadata.');$rows[]=$row;}}finally{if($statement)$statement->closeCursor();$this->db->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,$buffered);}return $rows;
    }
    private function file(array $row,string $scope):?array
    {
        $root=realpath($this->directory);$path=rtrim($this->directory,'/\\').'/'.$row['id'].'.webp';clearstatcache(true,$path);$resolved=realpath($path);
        if($root===false||!is_dir($root)||$resolved===false||!str_starts_with($resolved,rtrim($root,'/\\').DIRECTORY_SEPARATOR)||is_link($path)||!is_file($path)||!is_readable($path)){$this->error($scope,'Thiếu file WebP gốc hoặc file không nằm trực tiếp trong thư mục media hợp lệ.');return null;}
        if(filesize($path)!==(int)$row['bytes']){$this->error($scope,'Số byte file khác metadata nguồn.');return null;}$image=@getimagesize($path);if(!$image||($image['mime'] ?? '')!=='image/webp'||$image[0]!==(int)$row['width']||$image[1]!==(int)$row['height']){$this->error($scope,'File không phải WebP hoặc kích thước khác metadata nguồn.');return null;}$hash=hash_file('sha256',$path);if($hash===false){$this->error($scope,'Không đọc được file để kiểm tra.');return null;}return ['path'=>$path,'hash'=>$hash];
    }
    private static function canonical(array $row,array $columns):array{$out=[];foreach($columns as $column)$out[$column]=$column==='created_at'?self::timestamp($row[$column]):(string)$row[$column];return $out;}
    public function run(string $sourceDatabase,bool $apply=false):array
    {
        self::identifier($sourceDatabase);$target=(string)$this->db->query('SELECT DATABASE()')->fetchColumn();self::identifier($target);if(strcasecmp($sourceDatabase,$target)===0)throw new InvalidArgumentException('Database staging phải khác database PHP đích.');$this->errors=[];$this->bytes=0;$contract=json_decode(file_get_contents(dirname(__DIR__).'/docs/TRANSFER-CONTRACT.json'),true,512,JSON_THROW_ON_ERROR);$columns=$contract['mediaTables']['media'];
        $report=['scope'=>'media-metadata-only','mode'=>$apply?'apply':'dry-run','sourceDatabase'=>$sourceDatabase,'targetDatabase'=>$target,'ready'=>false,'applied'=>false,'counts'=>['sourceRows'=>0,'newRows'=>0,'matchingRows'=>0,'checkedFileBytes'=>0,'insertedRows'=>0],'fingerprint'=>null,'errors'=>[],'notImportedTables'=>[]];
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');if(!$apply)$this->db->exec('SET TRANSACTION READ ONLY');$this->db->beginTransaction();try{
            $schema=$this->query('SELECT TABLE_NAME,TABLE_TYPE,ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=?',[$target])->fetchAll(PDO::FETCH_UNIQUE|PDO::FETCH_ASSOC);$sourceSchema=$this->query('SELECT TABLE_NAME,TABLE_TYPE,ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=?',[$sourceDatabase])->fetchAll(PDO::FETCH_UNIQUE|PDO::FETCH_ASSOC);
            foreach(array_keys($sourceSchema) as $name)if(str_starts_with($name,'jm_transfer_')&&$name!=='jm_transfer_media')$report['notImportedTables'][]=$name;sort($report['notImportedTables']);
            foreach(['jingo_media','jingo_catalog_locks','jingo_audit'] as $name)if(!isset($schema[$name])||$schema[$name]['TABLE_TYPE']!=='BASE TABLE'||strtoupper($schema[$name]['ENGINE'] ?? '')!=='INNODB')$this->error($name,'Thiếu bảng InnoDB; chạy php bin/install.php.');if(!isset($sourceSchema['jm_transfer_media'])||$sourceSchema['jm_transfer_media']['TABLE_TYPE']!=='BASE TABLE'||strtoupper($sourceSchema['jm_transfer_media']['ENGINE'] ?? '')!=='INNODB')$this->error('jm_transfer_media','Thiếu bảng staging InnoDB.');
            foreach([[$target,'jingo_media'],[$sourceDatabase,'jm_transfer_media']] as [$database,$table]){$actual=$this->query('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=? AND TABLE_NAME=?',[$database,$table])->fetchAll(PDO::FETCH_COLUMN);$expected=$columns;sort($actual);sort($expected);if($actual!==$expected)$this->error($table,'Danh sách cột khác contract; không tự bỏ cột.');}
            $types=$this->query('SELECT COLUMN_NAME,DATA_TYPE,CHARACTER_MAXIMUM_LENGTH,CHARACTER_SET_NAME,DATETIME_PRECISION FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=? AND TABLE_NAME=?',[$target,'jingo_media'])->fetchAll(PDO::FETCH_ASSOC);foreach($types as $type){$name=$type['COLUMN_NAME'];if($name==='created_at'){if($type['DATA_TYPE']!=='datetime'||(int)$type['DATETIME_PRECISION']!==6)$this->error('created_at','Cần DATETIME(6); chạy migration 016 để giữ microsecond.');}elseif(in_array($name,['width','height','bytes'],true)){if(!in_array($type['DATA_TYPE'],['int','bigint'],true))$this->error($name,'Kiểu số đích không phù hợp.');}else{$size=['id'=>36,'filename'=>200,'alt'=>300,'created_by'=>64][$name] ?? PHP_INT_MAX;if(!in_array($type['DATA_TYPE'],['char','varchar','text','mediumtext','longtext'],true)||(int)$type['CHARACTER_MAXIMUM_LENGTH']<$size)$this->error($name,'Trường chuỗi đích ngắn hơn contract.');if($name!=='id'&&$type['CHARACTER_SET_NAME']!=='utf8mb4')$this->error($name,'Trường nội dung đích cần utf8mb4.');}}
            if(!$this->errors&&!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog'".($apply?' FOR UPDATE':''))->fetchColumn())$this->error('catalog','Thiếu khóa catalog.');if($this->errors){$report['errors']=$this->errors;$this->db->rollBack();return $report;}
            $source=$this->rows($sourceDatabase,'jm_transfer_media');$existing=[];foreach($this->rows($target,'jingo_media',$apply) as $row){$key=strtolower($row['id']);if(isset($existing[$key]))$this->error('jingo_media','Trùng ID đích khác chữ hoa/thường.');$existing[$key]=$row;}$report['counts']['sourceRows']=count($source);$seen=[];$pending=[];$fingerprints=[];
            foreach($source as $index=>$row){$scope='media row '.($index+1);$id=$row['id'];if(!is_string($id)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$id)||!self::text($row['filename'],200)||!self::text($row['alt'],300)||!self::text($row['created_by'],64)||!self::integer($row['width'],25000000)||!self::integer($row['height'],25000000)||!self::integer($row['bytes'],self::MAX_FILE)||!self::timestamp($row['created_at'])||(int)$row['width']*(int)$row['height']>25000000){$this->error($scope,'ID, metadata, thời gian hoặc giới hạn file không hợp lệ.');continue;}$key=strtolower($id);if(isset($seen[$key]))$this->error($scope,'Trùng ID nguồn.');$seen[$key]=true;$canonical=self::canonical($row,$columns);$file=$this->file($row,$scope);if(!$file)continue;$report['counts']['checkedFileBytes']+=(int)$row['bytes'];$fingerprints[]=json_encode([$canonical,$file['hash']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);
                if(isset($existing[$key])){if(self::canonical($existing[$key],$columns)!==$canonical)$this->error($scope,'ID đã có nhưng metadata khác; không ghi đè.');else $report['counts']['matchingRows']++;}else{$pending[]=['row'=>$row,'file'=>$file,'scope'=>$scope];$report['counts']['newRows']++;}}
            sort($fingerprints,SORT_STRING);$report['fingerprint']=hash('sha256',implode("\n",$fingerprints));$report['errors']=$this->errors;$report['ready']=!$this->errors;if(!$apply||!$report['ready']){$this->db->rollBack();return $report;}
            $quoted=implode(',',array_map(fn($column)=>'`'.$column.'`',$columns));$insert=$this->db->prepare('INSERT INTO jingo_media ('.$quoted.') VALUES ('.implode(',',array_fill(0,count($columns),'?')).')');foreach($pending as $plan){$current=$this->file($plan['row'],$plan['scope']);if(!$current||!hash_equals($plan['file']['hash'],$current['hash']))throw new RuntimeException('File đã thay đổi trong lúc nhập.');$insert->execute(array_map(fn($column)=>$plan['row'][$column],$columns));}
            if($pending)$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),'cli-import','media.import','media-transfer:'.$report['fingerprint']]);$this->db->commit();$report['applied']=true;$report['counts']['insertedRows']=count($pending);return $report;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
}
